INSERT INTO red_pill_verses (verse_id, claim_class, class_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'john' AND c.chapter_number = 8 AND v.verse_number = 12), 'title', 'The title transferred', 'I am the light of the world', $card$*Then spake Yahusha (Jesus) again unto them, saying, I am the light of the world: he that followeth me shall not walk in darkness, but shall have the light of life.* (John 8:12)

*Yahuah (LORD) is my light and my salvation; whom shall I fear? Yahuah (LORD) is the strength of my life; of whom shall I be afraid?* (Psalm 27:1)

*The sun shall be no more thy light by day; neither for brightness shall the moon give light unto thee: but Yahuah (LORD) shall be unto thee an everlasting light, and thy Elohim (God) thy glory.* (Isaiah 60:19)

*Yahuah (LORD) is my light* — David's confession, and Isaiah's promise of the age to come: Yahuah (LORD) himself an everlasting light in place of the sun. The one speaking in the treasury of the temple claims the title as his own present tense — *I am the light of the world* — and attaches to it what only the source of light can give: *the light of life.*$card$, '{"Psalm 27:1","Isaiah 60:19"}'::TEXT[], 'free', NOW())
