INSERT INTO red_pill_verses (verse_id, claim_class, class_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'revelation' AND c.chapter_number = 22 AND v.verse_number = 12), 'title', 'The title transferred', 'My reward is with me', $card$*And, behold, I come quickly; and my reward is with me, to give every man according as his work shall be. I am Alpha and Omega, the beginning and the end, the first and the last.* (Revelation 22:12-13)

*Behold, Adonai Yahuah (the Lord GOD) will come with strong hand, and his arm shall rule for him: behold, his reward is with him, and his work before him.* (Isaiah 40:10)

Isaiah announces Adonai Yahuah (the Lord GOD) coming with strong hand — *behold, his reward is with him, and his work before him.* The voice at the end of the canon takes the sentence into the first person: *behold, I come quickly; and my reward is with me* — and seals it with the unshareable name: Alpha and Omega, the first and the last. Isaiah's coming Yahuah (God) speaks in Revelation as I.$card$, '{"Isaiah 40:10","Revelation 22:13"}'::TEXT[], 'free', NOW())
