INSERT INTO red_pill_verses (verse_id, claim_class, class_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'jude' AND c.chapter_number = 1 AND v.verse_number = 5), 'structural', 'Only possible if', 'The one who saved the people out of Egypt', $card$*I will therefore put you in remembrance, though ye once knew this, how that Yahuah (Lord), having saved the people out of the land of Egypt, afterward destroyed them that believed not.* (Jude 5)

*I am Yahuah Elohayka (the LORD thy God), which have brought thee out of the land of Egypt, out of the house of bondage.* (Exodus 20:2)

Sinai opens with the credential: *I am Yahuah Elohayka (the LORD thy God), which have brought thee out of the land of Egypt.* The exodus is Yahuah (God)'s signature act — the one he names himself by. Jude asks his readers to REMEMBER who saved the people out of Egypt and then judged the unbelieving — and he writes it of the Lord his brother-after-the-flesh served. The Master Jude serves and the Elohim (God) of the exodus are one and the same, or the remembrance fails.$card$, '{"Exodus 20:2"}'::TEXT[], 'free', NOW())
