    last_reviewed_at = NOW(),
    updated_at = NOW();

INSERT INTO red_pill_verses (verse_id, claim_class, class_label, card_title, card_md, anchor_refs, tier_required, last_reviewed_at)
VALUES ((SELECT v.id FROM verses v JOIN chapters c ON c.id = v.chapter_id JOIN books b ON b.id = c.book_id JOIN editions e ON e.id = b.edition_id WHERE e.slug = 'canon' AND b.slug = 'john' AND c.chapter_number = 19 AND v.verse_number = 37), 'structural', 'Only possible if', 'They shall look upon ME whom they have pierced', $card$*And again another scripture saith, They shall look on him whom they pierced.* (John 19:37)

*And I will pour upon the house of David, and upon the inhabitants of Jerusalem, the spirit of grace and of supplications: and they shall look upon me whom they have pierced, and they shall mourn for him, as one mourneth for his only son, and shall be in bitterness for him, as one that is in bitterness for his firstborn.* (Zechariah 12:10)

Read Zechariah's pronouns slowly. The speaker is Yahuah (LORD) — and he says *they shall look upon ME whom they have PIERCED, and they shall mourn for HIM.* Me, pierced; him, mourned — both in one breath, centuries before the spear. John stands at the cross and says this is that scripture. And the canon's last book seals it:

*Behold, he cometh with clouds; and every eye shall see him, and they also which pierced him: and all kindreds of the earth shall wail because of him. Even so, Amen.* (Revelation 1:7)

Yahuah (LORD) said *me.* The spear found flesh. The verse was only ever possible if the pierced one is the speaker — the Formed, Yahuah (God) come in the flesh, mourned as a firstborn son.$card$, '{"Zechariah 12:10","Revelation 1:7"}'::TEXT[], 'free', NOW())
