DO $verify$
DECLARE
    n INT;
BEGIN
    SELECT COUNT(*) INTO n FROM red_pill_verses;
    IF n < 39 THEN
        RAISE EXCEPTION 'session204 seed verify failed: % rows (expected >= 39)', n;
    END IF;
    RAISE NOTICE 'session204 seed verified: % witness verses live.', n;
END
$verify$;

COMMIT;
